import java.util.*;

class Solution {
  public int[] minimumTime(int n, int[][] edges, int[] disappear) {
    List<int[]>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] edge : edges) {
      graph[edge[0]].add(new int[] {edge[1], edge[2]});
      graph[edge[1]].add(new int[] {edge[0], edge[2]});
    }
    long[] distance = new long[n];
    Arrays.fill(distance, Long.MAX_VALUE);
    distance[0] = 0;
    PriorityQueue<long[]> queue = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
    queue.offer(new long[] {0, 0});
    while (!queue.isEmpty()) {
      long[] current = queue.poll();
      long time = current[0];
      int node = (int) current[1];
      if (time != distance[node]) continue;
      for (int[] edge : graph[node]) {
        int next = edge[0];
        long arrival = time + edge[1];
        if (arrival < disappear[next] && arrival < distance[next]) {
          distance[next] = arrival;
          queue.offer(new long[] {arrival, next});
        }
      }
    }
    int[] answer = new int[n];
    for (int i = 0; i < n; i++) answer[i] = distance[i] == Long.MAX_VALUE ? -1 : (int) distance[i];
    return answer;
  }
}
